  /**
   * Creates an iterator over the given domain type. If this is a tuple, it
   * first iterates over the plain types; if varargs are present, it then
   * iterates over them indefinitely. If this is any other type, it is the
   * singleton iterator.
   */
  def typeIterator(dom: Type): Iterator[Type] = dom match {
    case STupleType(_, elts, None, _) => elts.iterator
    case STupleType(_, elts, Some(varargs), _) =>
      elts.iterator ++ new Iterator[Type] {
        def hasNext = true
        def next() = varargs
      }
    case _ => Iterator.single(dom)
  }

  /**
   * Creates an iterator over the given domain type. If this is a tuple, it
   * first iterates over the plain types; if varargs are present, it then
   * iterates over them indefinitely. If this is any other type, including a
   * void type, it is the singleton iterator.
   */
  def typeIteratorVoid(dom: Type): Iterator[Type] = dom match {
    case STupleType(_, Nil, None, _) => Iterator.single(dom)
    case _ => typeIterator(dom)
  }

  /**
   * Zip the given iterator of elements with the type iterator for the given
   * domain type.
   */
  def zipWithDomain[T](elts: Iterator[T], dom: Type): Iterator[(T, Type)] = {
    val first = elts.next
    if (!elts.hasNext)
      Iterator.single((first, dom))
    else
      (Iterator.single(first) ++ elts) zip typeIterator(dom)
  }

  /** Same as the other zipWithDomain but uses lists. */
  def zipWithDomain[T](elts: List[T], dom: Type): List[(T, Type)] = elts match {
    case List(elt) => List((elt, dom))
    case _ => (elts.iterator zip typeIterator(dom)).toList
  }

  /**
   * Zip the given iterator of elements with the type iterator for the given
   * domain type, considering void as a single type.
   */
  def zipWithRhsType[T](elts: Iterator[T], dom: Type): Iterator[(T, Type)] =
    elts zip typeIteratorVoid(dom)

  /** Same as the other zipWithRhsType but uses lists. */
  def zipWithRhsType[T](elts: List[T], dom: Type): List[(T, Type)] =
    (zipWithRhsType(elts.iterator, dom)).toList

  /**
   * Determine if there are enough of the given elements to cover all
   * constituent types of the given type.
   */
  def enoughElementsForType[T](elts: List[T], typ: Type): Boolean =
    elts.size == 1 || (typ match {
      case STupleType(_, typs, None, _) => typs.size == elts.size   // no varargs, keywords ignored for now
      case STupleType(_, typs, Some(_), _) => false //typs.size <= elts.size    // varargs, but ignored for now (as are keywords)
      case _ => false
    })

  /** Get the nth constituent type of the given type. */
  def getTypeAt(typ: Type, index: Int): Option[Type] = {
    if (index < 0) return None
    val itr = typeIterator(typ).drop(index)
    if (itr.hasNext) Some(itr.next) else None
  }


  /**
   * Checks whether an arrow type is applicable to the given args. If so, then
   * the [possiblly instantiated] arrow type along with any inferred static
   * args are returned.
   */
  def inferStaticParams(fnType: ArrowType,
    argType: Type,
    context: Option[Type])(implicit analyzer: TypeAnalyzer): Option[(ArrowType, List[StaticArg])] = {

    // Builds a constraint given the arrow with inference variables.
    def makeConstraint(infArrow: ArrowType, map: Map[Op, Op]): CFormula = {

      // argType <:? dom(infArrow) yields a constraint, C1
      val domainConstraint = checkSubtype(argType, infArrow.getDomain)

      // if context given, C := C1 AND range(infArrow) <:? context
      val rangeConstraint = context.map(t =>
        checkSubtype(infArrow.getRange, t)).getOrElse(True)

      and(domainConstraint, rangeConstraint)
    }

    // Do the inference.
    inferStaticParamsHelper(fnType, makeConstraint, false, true, true)
  }

  /**
   * Helper that performs the inference of static params in `typ`. Infers all
   * static params, lifted and unlifted, by default; behavior can be changed at
   * the call site by setting the `inferLifted` and `inferUnlifted` flags.
   * 
   * @param typ The type schema for which we want to infer an instantiation.
   * @param constraintMaker A function that, given a type with inference
   *     variables, returns the constraints to be satisfied for the
   *     instantiation.
   * @param inferLifted If true, lifted static parameters will be inferred. The
   *     default value is true.
   * @param inferUnlifted If true, unlifted static parameters will be inferred.
   *     The default value is false.
   * @param toBounds If true, the static arguments are those of a call: a type
   *     parameter that no lower bound fixes takes the intersection of its
   *     upper bounds, and never BottomType (Formula.solveToBounds). The
   *     default value is false.
   * @return If successful, a pair of the instantiated type and the static args
   *     that instantiated it.
   */
  def inferStaticParamsHelper[T <: Type](typ: T,
      				   	 constraintMaker: (T, Map[Op, Op]) => CFormula,
					 inferLifted: Boolean = true,
					 inferUnlifted: Boolean = true,
					 toBounds: Boolean = false)(implicit analyzer: TypeAnalyzer):
        Option[(T, List[StaticArg])] = {

    // Substitute inference variables for static parameters in typ.

    // 1. build substitution S = [T_i -> $T_i]
    // 2. instantiate fnType with S to get an arrow type with inf vars, infArrow
    val sparamsIni = getStaticParams(typ).filter { s =>
      (s.isLifted && inferLifted) || (!s.isLifted && inferUnlifted)
    }
    //Fix to avoid getting dominating variables
    val sparams: List[StaticParam] = sparamsIni.filter(_.getDominatesClause().isEmpty())
    val domparams: List[StaticParam] = sparamsIni.filterNot(_.getDominatesClause().isEmpty())

    val sargs = sparams.map(makeInferenceArg) ++ domparams.map(makeInferenceArg)

    val ops = Map((sparams.zip(sargs).flatMap(getOps)):_*)
    val infTyp = staticInstantiation(sargs,
      typ,
      applyLifted = inferLifted,
      applyUnlifted = inferUnlifted).
      getOrElse(return None).asInstanceOf[T]
//   println("Static params helper has infTyp " + infTyp)

    val constraint = constraintMaker(infTyp, ops)
//   println("Static params helper has constraint " + constraint)

    // 5. build bounds map B = [$T_i -> S(UB(T_i))]
    val infVars = sargs.flatMap(staticArgType)
    val sparamBounds = sparams.flatMap(staticParamBoundType).flatMap { t =>
      staticInstantiation(sargs,
        insertStaticParams(t, sparams),
        applyLifted = inferLifted,
        applyUnlifted = inferUnlifted)
    }.map(t => TPrimitive(Set(), Set(), Set(t), Set(  ), Set(), Set()))     // GLS 2/6/2012 Don't allow BottomType to be an upper bound (this could be loosened for some vars but not others)
    // GLS 2/6/2012 The real fix would be to prohibit BottomType as an upper bound only for vars that are in contravariant position in the signature.
    val upperBounds = And(Map(infVars.zip(sparamBounds): _*), Map())
//   println("Static params helper has bounds " + bounds)

   val sparamLowerBounds = domparams.flatMap(staticParamLowerBoundType).flatMap { t =>
      staticInstantiation(sargs,
        insertStaticParams(t, sparams),
        applyLifted = inferLifted,
        applyUnlifted = inferUnlifted)
    }.map(t => TPrimitive(Set(t), Set(), Set(), Set(), Set(), Set()))

    val lowerBounds = And(Map(infVars.zip(sparamLowerBounds): _*), Map())

    // 6. solve C to yield a substitution S' = [$T_i -> U_i]
    val bounded = and(constraint, and(upperBounds,lowerBounds))
    val (tSub, oSub, nSub) = (if (toBounds) solveToBounds(bounded) else solve(bounded)).getOrElse(return None)

    // 7. instantiate infArrow with [U_i] to get resultArrow
    val prenorm = tSub(infTyp)
    val extendedAnalyzer = analyzer.extendJ(prenorm.getInfo().getStaticParams(),None)
    val resultTyp = extendedAnalyzer.normalize(prenorm).asInstanceOf[T]
//   println("Static params helper normalized " + prenorm + " to " + resultTyp);

    // 8. return (resultArrow,StaticArgs([U_i]))
    val resultArgs = sargs.map {
      case STypeArg(info, lifted, typ) =>  STypeArg(info, lifted, tSub(typ))
      case SOpArg(info, lifted, op) => SOpArg(info, lifted, oSub(op))
      case SIntArg(info, lifted, e) => SIntArg(info, lifted, nSub(e))
      case sarg => sarg
    }

    Some((resultTyp, resultArgs))
  }


  //TODO: Make op constraint
  def inferLiftedStaticParams(fnType: ArrowType, argType: Type,
      mOps: Option[(Op,Op)])(implicit analyzer: TypeAnalyzer): Option[(ArrowType, List[StaticArg])] = {

    val sparams = getStaticParams(fnType).filter(_.isLifted)
    if (sparams.isEmpty || fnType.getMethodInfo.isNone) return Some((fnType, Nil))

    // Builds a constraint given the arrow with inference variables.
    def makeConstraint(infArrow: ArrowType, map: Map[Op, Op]): CFormula = {
      // Get the type of the `self` arg and form selfArg <:? selfType
      val SMethodInfo(selfType, selfPosition) = infArrow.getMethodInfo.unwrap
      val tConstraint = getTypeAt(argType, selfPosition) match {
        case Some(selfArgType) => checkSubtype(selfArgType, selfType)
        case None => False
      }
      val oConstraint = mOps match {
        case Some((op, ov_op)) => 
          analyzer.equivalent(op, map.getOrElse(analyzer.normalize(ov_op), ov_op))
        case None => True
      }
      and(tConstraint, oConstraint)
    }

    // Do the inference.
    inferStaticParamsHelper(fnType, makeConstraint, true, false, true)
  }

  /**
   * Define an ordering relation on arrows with their instantiations. That is,
   * is candidate1 more specific than candidate2? A generic candidate may carry
   * its declared arrow, and is then compared on its declared domain: between
   * two candidates without coercion, by subtyping on declared domains; between
   * two with coercion, by that when it relates them one way, and otherwise by
   * the coercion chapter's order on their domains. The coercions the promotion
   * introduced into a promoted candidate are not counted.
   */
  def moreSpecificCandidate(candidate1: AppCandidate,
    candidate2: AppCandidate,
    declared1: Option[ArrowType] = None,
    declared2: Option[ArrowType] = None,
    promoted1: Boolean = false,
    promoted2: Boolean = false)(implicit coercions: CoercionOracle): Boolean = {

    val AppCandidate(SArrowType(_, domain1, range1, _, _, mi1), _, args1, _, _) = candidate1
    val AppCandidate(SArrowType(_, domain2, range2, _, _, mi2), _, args2, _, _) = candidate2

        args: List[Either[Expr, FnExpr]],
        promote: Option[List[StaticArg]])
        (implicit errorFactory: ApplicationErrorFactory)
         : Either[AppCandidate, OverloadingError] = {
  def notApplicable = Right(errorFactory.makeNotApplicableError(preCandidate.arrow, args))
  if (args.exists(_.isRight)) return notApplicable
  val checked = args.map(_.left.get)
  val params = getStaticParams(arrow).filter(!_.isLifted)
  // The order in which inferStaticParams returns the static args.
  val order = params.filter(_.getDominatesClause.isEmpty) ++ params.filterNot(_.getDominatesClause.isEmpty)
  val names: Set[IdOrOp] = params.map(_.getName).toSet
  val typeNames: Set[IdOrOp] = params.filter(_.getKind.isInstanceOf[KindType]).map(_.getName).toSet
  def mentioned(t: Type): Set[IdOrOp] = {
    var found = Set[IdOrOp]()
    object finder extends Walker {
      override def walk(node: Any): Any = node match {
        case n: VarType if names(n.getName) => found += n.getName; node
        case n: IntRef if names(n.getName) => found += n.getName; node
        case _ => super.walk(node)
      }
    }
    finder(t); found
  }
  def bare(d: Type): Option[IdOrOp] = d match {
    case v: VarType if typeNames(v.getName) => Some(v.getName)
    case _ => None
  }
  // An argument whose trait's comprises clause lists one type at where-clause
  // sizes (TypeAnalyzer.opensSizes) is opened once for the call, so that its
  // admission below meets the size its inference bound; a subtype check would
  // open it afresh.
  def opened(t: Type): Type = t match {
    case tt: TraitType if analyzer.opensSizes(tt) => analyzer.comprisedTypes(tt) match {
      case Some(cs) if cs.size == 1 => cs.head
      case _ => t
    }
    case _ => t
  }
  val argTypes = checked.map(e => opened(normalize(getType(e).get)))
  val positions = zipWithDomain(argTypes, arrow.getDomain)
  val numerals = zipWithDomain(checked, arrow.getDomain).map(p => isNumeral(p._1))
  val fixedElsewhere = positions.filter(p => bare(p._2).isEmpty).flatMap(p => mentioned(p._2)).toSet
  val chosen = positions.flatMap(p => bare(p._2)).distinct.filterNot(fixedElsewhere)
  def valueOf(sargs: List[StaticArg], n: IdOrOp): Option[Type] =
    order.zip(sargs).collectFirst { case (sp, STypeArg(_, _, t)) if sp.getName == n => t }
  def own(n: IdOrOp): List[(Type, Expr)] =
    positions.zip(checked).collect { case ((t, d), e) if bare(d) == Some(n) &&
      !t.isInstanceOf[BottomType] && !hasInferenceVars(t) => (t, e) }
  // The types a chosen parameter may take: its args' types, the types they
  // coerce to, and its declared bound. None leaves it to its upper bounds.
  def named(n: IdOrOp): List[Type] = {
    val ts = own(n).map(_._1)
    val bound = params.find(_.getName == n).toList.
                  flatMap(sp => toListFromImmutable(sp.getExtendsClause)).
                  filter(b => b.isInstanceOf[TraitType] && mentioned(b).isEmpty &&
                              !Set("Object", "Any")(b.asInstanceOf[TraitType].getName.getText))
    (ts ++ ts.flatMap(coercions.getCoercionTargetsFrom(_)) ++ bound).distinct
  }
  val choices: List[List[Option[Type]]] = chosen.map { n =>
    promote match {
      case Some(sargs) => valueOf(sargs, n) match {
        case Some(_: UnionType) => None :: named(n).map(Some(_))
        case v => List(v)
      }
      case None => None :: named(n).map(Some(_))
    }
  }
  if (promote.isDefined && !chosen.exists(n => valueOf(promote.get, n).exists(_.isInstanceOf[UnionType])))
    return notApplicable
  val combos = choices.foldRight(List(List[Option[Type]]())) { (cs, acc) => for (c <- cs; m <- acc) yield c :: m }
  if (combos.size > 64) return notApplicable
  def attempt(combo: List[Option[Type]]): Option[AppCandidate] = {
    val pick = Map(chosen.zip(combo): _*)
    // Only the positions that fix a static parameter by subtyping, the
    // chosen types and the context constrain the inference.
    val tys = positions.map { case (a, d) => bare(d) match {
      case Some(n) => pick.getOrElse(n, None)
      case None => if (mentioned(d).isEmpty) None else Some(a)
    }}
    def constraint(inf: ArrowType, ops: Map[Op, Op]): CFormula =
      Formula.and(context.map(c => analyzer.subtype(inf.getRange, c)).toList ++
                  zipWithDomain(tys, inf.getDomain).collect { case (Some(t), d) => analyzer.subtype(t, d) })
    val (resultArrow, sargs) =
      inferStaticParamsHelper(arrow, constraint, false, true, true).getOrElse(return None)
    if (hasInferenceVars(resultArrow) || hasSizeInferenceVars(sargs)) return None
    val newArgs = zipWithDomain(checked.zip(argTypes), resultArrow.getDomain).map { case ((e, a), p) =>
      if (isSubtype(a, p)) e else coercions.buildCoercion(e, p).getOrElse(return None)
    }
    val newArgTypes = newArgs.zip(checked.zip(argTypes)).map { case (n, (e, a)) => if (n eq e) a else getType(n).get }
    if (!isSubtype(NF.makeMaybeTupleType(NF.typeSpan, toJavaList(newArgTypes)), resultArrow.getDomain)) return None
    Some(AppCandidate(resultArrow, sargs, newArgs, preCandidate.overloading, preCandidate.fnl))
  }
  val found = combos.flatMap(attempt(_))
  def noWider(a: AppCandidate, b: AppCandidate) = chosen.forall { n =>
    (valueOf(a.sargs, n), valueOf(b.sargs, n)) match {
      case (Some(s), Some(t)) => coercions.noLessSpecific(s, t)
      case _ => false
    }
  }
  def narrowest(cs: List[AppCandidate]) = cs.find(a => cs.forall(noWider(a, _)))
  narrowest(found).orElse {
    // A parameter that numerals alone fix, with no one type narrowest: the
    // numerals are read as ZZ32, or as ZZ64 or ZZ by magnitude.
    val byNumerals = chosen.filter(n => own(n).nonEmpty && own(n).forall(p => isNumeral(p._2)))
    if (byNumerals.isEmpty) None
    else {
      val readings = byNumerals.map(n => numeralReading(own(n).map(_._2)))
      if (readings.exists(_.isEmpty)) None
      else narrowest(found.filter(c => byNumerals.zip(readings.map(_.get)).forall { case (n, r) =>
               valueOf(c.sargs, n).exists(coercions.substitutableFor(r, _)) }))
    }
  } match {
    case Some(c) => Left(c)
    case None => notApplicable
  }
}

/** Whether the expression is a numeral, or a size used as a value, which the checker types as one. */
def isNumeral(e: Expr): Boolean = getType(e) match {
  case Some(t) => Formula.isTrue(analyzer.equivalent(t, Types.INT_LITERAL))
  case None => false
}

/**
 * The type numerals are read as when nothing narrower fixes them: ZZ32, or
 * ZZ64 or ZZ when a numeral's value does not fit; the supertype or coercion
 * target of the numeral type with that name.
 */
def numeralReading(es: List[Expr]): Option[Type] = {
  val big = es.collect { case l: IntLiteralExpr => l.getIntVal }
  val name =
    if (big.forall(v => v.bitLength < 32)) "ZZ32"
    else if (big.forall(v => v.bitLength < 64)) "ZZ64"
    else "ZZ"
  (analyzer.ancestors(Types.INT_LITERAL).toList.collect { case t: TraitType => t } ++
   coercions.getCoercionTargetsFrom(Types.INT_LITERAL)).find(_.getName.getText == name)
}

