               : (List[GeneratorClause], List[LValue]) = generators match {

  case Nil => (Nil, Nil)
  case hd::Nil =>
    val (clause, binds) = generatorClauseGetBindings(hd, false)
    (List[GeneratorClause](clause), binds)
  case hd::tl =>
